mapper.update:
update fly_block
block_name = #{blockName}, block_type = #{blockType}, content = #{content}, item_count = #{itemCount}, cache_seconds = #{cacheSeconds}, status = #{status}, sort = #{sort}, update_time = now()
where id = #{id}

mapper.select:
select from fly_block_item where block_id = #{blockId}
and status = 1 and (start_time is null or start_time <= now()) and (end_time is null or end_time >= now())
order by sort asc, id desc
